import{_ as a,c as r,o as t,ag as n}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"UI architecture practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/ui-architecture.md","filePath":"practice/frontend/ui-architecture.md"}'),s={name:"practice/frontend/ui-architecture.md"};function i(o,e,c,d,l,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ui-architecture-practice" tabindex="-1">UI architecture practice <a class="header-anchor" href="#ui-architecture-practice" aria-label="Permalink to “UI architecture practice”">​</a></h1><p><strong>Learner status: outstanding.</strong> Prerequisites: F01–F05 and <a href="./../../senior_growth/EngX_Quality/Large_Data_Workflow.html">the large-data lesson</a>. This refines P-328, not a separate full application.</p><h2 id="scope-acceptance-and-failure-cases" tabindex="-1"><span class="hub-section-number">1 </span>Scope, acceptance and failure cases <a class="header-anchor" href="#scope-acceptance-and-failure-cases" aria-label="Permalink to “1 Scope, acceptance and failure cases”">​</a></h2><ol><li>Connect an authorized, byte-bounded HTTP adapter and a real database endpoint. Seed at least 10,000 records including equal sort values. Prove stable ordering, cursor filter/tenant binding and snapshot expiry using integration tests. Record your chosen consistency policy instead of assuming keyset pagination freezes data.</li><li>Return query A after query B, including an adapter that ignores abort; B must remain visible. Unmount during a read and verify cancellation plus no later state commit. Return duplicate IDs, 51 rows, invalid JSON and an expired snapshot; reject safely and provide a restart route. Test the 100-ID cap across at least three pages and a selected ID that disappears server-side before action.</li><li>Save a Unicode query, restore after reload, change account/tenant and deny storage access. Restore must fetch a fresh authorized first page; no stale cursor or row may be restored. Implement “delete saved view” and logout cleanup before enabling device persistence for users.</li><li>Use keyboard and a screen reader in a native browser: labels, caption/header associations, selected state, status and heading focus must remain understandable across load/error/restart. Test zoom/reflow and return focus behavior. Record observations; fix failures rather than inferring accessibility from semantic markup alone.</li><li>Define a device/network/workload and measure input responsiveness, transferred bytes, page rendering and heap after repeated navigation. Proposed budgets: at most 50 rendered data rows, 100 selected IDs, and no accumulation of old page arrays; choose a measured p95 interaction target and payload byte limit with product stakeholders. Automated fixture tests establish behavior, not those runtime performance results.</li></ol><p>Learner implementation and evidence are still required. The local fixture neither deploys the application nor establishes professional readiness.</p><h2 id="evidence" tabindex="-1"><span class="hub-section-number">2 </span>Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “2 Evidence”">​</a></h2><p>Retain adapter/DB integration results, failure→fix→retest, source/runtime versions, browser/keyboard observations and explicit unperformed screen-reader/zoom/device checks.</p>',7)])])}const f=a(s,[["render",i]]);export{h as __pageData,f as default};
